TLM.f("Sancti/01-20",{"officium":"Ss. Fabiani et Sebastiani Martyrum","rule":["vide C3;","Gloria"],"fallback":"Commune/C3","from":{"Introitus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 78:11-12; 78:10"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."},{"k":"ref","la":"Ps 78:1"},{"k":"text","la":"Deus, venérunt gentes in hereditátem tuam: polluérunt templum sanctum tuum: posuérunt Jerúsalem in pomórum custódiam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."}],"Oratio":[{"k":"text","la":"Infirmitátem nostram réspice, omnípotens Deus: et, quia pondus própriæ actiónis gravat, beatórum Mártyrum tuórum Fabiáni et Sebastiáni intercéssio gloriósa nos prótegat."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 11:33-39"},{"k":"text","la":"Fratres: Sancti per fidem vicérunt regna, operáti sunt justítiam, adépti sunt repromissiónes, obturavérunt ora leónum, exstinxérunt ímpetum ignis, effugérunt áciem gládii, convaluérunt de infirmitáte, fortes facti sunt in bello, castra vertérunt exterórum: accepérunt mulíeres de resurrectióne mórtuos suos: álii autem disténti sunt, non suscipiéntes redemptiónem, ut meliórem invenírent resurrectiónem: alii vero ludíbria et vérbera expérti, ínsuper et víncula et cárceres: lapidáti sunt, secti sunt, tentáti sunt, in occisióne gládii mórtui sunt: circuiérunt in melótis, in péllibus caprínis, egéntes, angustiáti, afflicti: quibus dignus non erat mundus: in solitudínibus errantes, in móntibus et spelúncis et in cavérnis terræ. Et hi omnes testimónio fídei probáti, invénti sunt in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 144:10-11"},{"k":"text","la":"Sancti tui, Dómine, benedícent te: glóriam regni tui dicent. Allelúja."}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 6:17-23"},{"k":"text","la":"In illo témpore: Descéndens Jesus de monte, stetit in loco campéstri, et turba discipulórum ejus, et multitúdo copiósa plebis ab omni Judǽa, et Jerúsalem, et marítima, et Tyri, et Sidónis, qui venérant, ut audírent eum et sanaréntur a languóribus suis. Et, qui vexabántur a spirítibus immúndis, curabántur. Et omnis turba quærébat eum tángere: quia virtus de illo exíbat, et sanábat omnes. Et ipse, elevátis oculis in discípulos suos, dicébat: Beáti, páuperes: quia vestrum est regnum Dei. Beáti, qui nunc esurítis: quia saturabímini. Beáti, qui nunc fletis: quia ridébitis. Beáti éritis, cum vos óderint hómines, et cum separáverint vos et exprobréverint, et ejécerint nomen vestrum tamquam malum, propter Fílium hóminis. Gaudéte in illa die et exsultáte: ecce enim, merces vestra multa est in cœlo."}],"Offertorium":[{"k":"ref","la":"Ps 31:11"},{"k":"text","la":"Lætámini in Dómino et exsultáte, justi: et gloriámini, omnes recti corde."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, beatórum Mártyrum tuórum Fabiáni et Sebastiáni dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 6:18; 6:19"},{"k":"text","la":"Multitúdo languéntium, et qui vexabántur a spirítibus immúndis, veniébant ad eum: quia virtus de illo exíbat, et sanábat omnes."}],"Postcommunio":[{"k":"text","la":"Refécti participatióne múneris sacri, quǽsumus, Dómine, Deus noster: ut, cujus exséquimur cultum, intercedéntibus sanctis Martýribus tuis Fabiáno et Sebastiáno, sentiámus efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"fb339773d9c17ccf":{"t":"Ps 78, 11 i 12 i 10, Ps 78, 1\n(Ps 78, 11 i 12 i 10) Neka uzađu pred lice tvoje, Gospodine, uzdasi sužanjski, sedmerostruko vrati susjedima našim. Osveti prolivenu krv slugu svojih! (Ps 78, 1) Bože, narodi prodiru u nasljedstvo tvoje, skvrne sveti hram tvoj, pretvaraju Jeruzalem u razvaline.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 78, 11 i 12 i 10) Neka uzađu pred lice tvoje, Gospodine, uzdasi sužanjski, sedmerostruko vrati susjedima našim. Osveti prolivenu krv slugu svojih!","kn":"(Ps. 78. 11, 12, 10). Vapaj zarobljenih neka dođe pred lice Tvoje, Gospodine; vrati susjedima našim sedmerostruko u krilo njihovO'; osveti krv slugu svojih, koja je prolivena! (Ps. 78, 1) Bože! Provalili su bezbožnici u Tvoju baštinu, Jeruzalem su pretvorili u razvalinu! Slava Ocu. Vapaj.","knRef":"Kniewald 1942, str. 484–485 (snimka 243) (OCR)"},"9353c7e708394218":{"t":"<i>Pomolimo se</i>.\nObazri se, Gospodine, na našu slabost, pa jer nas pritište težina vlastitog djelovanja, neka nas štiti slavni zagovor blaženih tvojih mučenika Fabijana i Sebastijana.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"7a00e935177c5afd":{"t":"Heb 11, 33-39\nČitanje Poslanice bl. Pavla apostola Hebrejima. Braćo, sveti su vjerom osvajali kraljevstva, činili pravdu, postigli obećanje, lavovima zatvarali ždrijela, gasili silu ognja, izbjegavali oštricu mača, ozdravljali od bolesti, bili su hrabri u borbi, rastjerivali neprijateljske vojske. Žene su primale svoje mrtve kao uskrsle. Jedni su stavljani na muke i nisu prihvaćali oslobođenja samo da bi postigli stalnije uskrsnuće. Drugi su podnosili pogrde i udarce, a osim toga okove i tamnice. Neki su opet bili kamenovani, piljeni, iskušavani, umirali su sasječeni mačem, obilazili obučeni u ovčjim ili kozjim kožama, u oskudici, nevolji i sramoti. Oni kojih svijet nije bio dostojan lutah su po pustinjama, gorama, špiljama i rupama zemlje. I svi su se ti prokušani u svjedočanstvu vjere našli u našem Gospodinu Isusu Kristu.","kn":"Čitanje poslanice bi. Pavla apostola Hebrejima (11, 33-39). Braćo! Sveti su pobijedili kraljevstva Po vjeri, činili pravdu, postigli obećanja. Lavovima fiu zatvorili usta, ugasili silu ognja, izbjegli oštrini mača, ozdravili od bolesti, bili su hrabri u ratu, razgonili neprijateljske vojske, a žene su po uskrsnuću dobivale svoje mrtve. Drugi stavljeni na muke nijesu primali otkupa, da postignu bolje uskrsnuće. Drugi su podnosili pogrde i udarce, još i okove i tamnice. Bili su kamenovani, piljeni, kušani, umirali su prosječeni mačem, obilazili su u ovčijim i kozijim kožama, u oskudici, nevolji i Q Sv. Fabijan i Sebastijan 20. I. sramoti. Oni, kojih svijet nije doetojam, lutali su po pustinjama 1 gorama i špiljama i rupama u zemlji. I ovi svi, prokušani svjedočanstvom vjere, našli su se u Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 484–485 (snimka 243) (OCR)"},"900fe5f70bb80158":{"t":"Izl 15, 11, Izl 15, 6\n(Izl 15, 11) Slavan je Bog u svojim svetima, divan u veličanstvu, čini čudesa. (Izl 15, 6) Snagom se proslavila desnica tvoja, Gospodine, desnica je tvoja uništila neprijatelje.\n\nPs 144, 10-11\n<i>Aleluja</i>, <i>aleluja</i>.\nNeka te Gospodine, blagoslivljaju sveti tvoji i neka propovijedaju o slavi kraljevstva tvojega. <i>Aleluja</i>.","kn":"(Izl. 15, 11). Slavan je Bog u svetima svojim, divan u veličanstvu, on čini čudesa. (Izl. 15, 6). Proslavila se desnica Tvoja, Gospodine, snagom svojom, desnica je Tvoja satrla neprijatelje!\n\nAleluja, aleluja. (Ps. 144, 10. 11.) Blagosiljali Te, Gospodine, sveti Tvoji, slavili kraljevstvo . Tvoje, aleluja.","knRef":"Kniewald 1942, str. 484–485 (snimka 243) (OCR)"},"67f4feac8d3daae0":{"t":"Lk 6, 17-23\nSlijedi sveto Evanđelje po Luki. U ono vrijeme siđe Isus s gore, zaustavi se na ravnici s mnoštvom svojih učenika i vrlo mnogo ljudi iz čitave Judeje, Jeruzalema, Primorja, Tira i Sidona, koji su došli da ga čuju i da se izliječe od svojih bolesti. I ozdravljali su oni koje su mučili nečisti duhovi. I sav ga se svijet htio dotaknuti, jer je iz njega izlazila moć, i sve je liječio. On podigne oči prema svojim učenicima i reče: Blago vama siromasima, jer je vaše Božje kraljevstvo. Blago vama koji sada gladujete, jer ćete se nasititi. Blago vama kada vas ljudi mrze i odbace, pogrde i prezru kao nečasne radi Sina Čovječjega. Radujte se i veselite u taj dan, jer je velika vaša plaća na nebu!","kn":"t Slijedi sveto evanđelje po Luki (6, 17-23). U ono vrijeme siđe Isus s gore, zaustavi se na ravnici s četom svojih učenika i vrlo mnogo ljudi iz sve Judeje i Jeruzalema i primorja i Tira i Sidona, koji su došli da ga čuju i liječe se od svojih bolesti. I ozdravljali su oni, koje su mučili nečisti duhovi. I sav je svijet htio da ga se dotakne, jer je iz njega Izlazila moć i liječio je sve. A o.n podigne^ oči na svoje učenike i reče: Blago vama siromasima, jer je vaše kraljevstvo nebesko. Blago vama, koji sada gladujete, jer ćete se nasltiti. Blago vama, koji sada plačete, jer ćete se smijati. Blago vama, kad vas ljudi mrze i odbace vas, pogrde i prezru kao nečasne radi Sina čovječjega. Radujte se^ onoga dana i veselite, jer je velika vaša plaća na nebu.","knRef":"Kniewald 1942, str. 484–485 (snimka 243) (OCR)"},"3214588b1ef80847":{"t":"Ps 31, 11\nRadujte se u Gospodinu i kličite, pravednici! Veselite se svi koji ste čestita srca.","kn":"(Ps. 31, 11). Radujte se u Gospodinu i kličite pravednici; veselite se svi, koji ste prava srca!","knRef":"Kniewald 1942, str. 470–471 (snimka 236) (OCR)"},"5ff45ca9e3b41ba3":{"t":"Dobrostivo primi, Gospodine, prinose koje ti posvećujemo po zaslugama blaženih tvojih mučenika Fabijana i Sebastijana i daj da nam postanu trajna pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"f28ef05f0ff95766":{"t":"Lk 6, 18 i 19\nMnoštvo bolesnika i onih koje su mučili zli duhovi dolazilo je k njemu, jer je moć izlazila iz njega i sve je ozdravljao.","kn":"(Lk. 6, 18, 19). Mnogi bolesnici i oni, koje su mučili nečisti dusi, dođoše, jer je iz njega izlazila sila i sve je iscjeljivao.","knRef":"Kniewald 1942, str. 486–487 (snimka 244) (OCR)"},"19b9129cba2c3457":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni sudjelovanjem u svetom daru, molimo, Gospodine Bože naš, da po zagovoru tvojih svetih mučenika Fabijana i Sebastijana osjetimo učinak tajne, koju slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Okrijepljeni svetim darovima molimo Te, Gospodine, Bože naš, da zagovorom svetih nmčenika Tvojih Fabijana i Sebastijana osjetimo djelovanje svetih tajna, koje izvršujemo. Po G. n.","knRef":"Kniewald 1942, str. 486–487 (snimka 244) (OCR)"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}]}}});
